// ─── File: BuilderDemo.java ───
package com.bank.builder;

import java.math.BigDecimal;
import java.util.logging.*;

public class BuilderDemo {
    private static final Logger log = Logger.getLogger(BuilderDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // FLUENT CHAIN: each setter returns the builder, build() locks it
        Order order = Order.builder()
            .tradeId("TRD-1001")
            .accountId("SAV2001")           // Rajesh
            .symbol("RELIANCE")
            .quantity(100)
            .price(new BigDecimal("2450.50"))
            .fee(new BigDecimal("50.00"))
            .orderType("MARKET")
            .notes("Rajesh monthly SIP")     // optional field
            .build();
        log.info(() -> "Built immutable order: " + order);
        log.info(() -> "Total cost = Rs." + order.totalCost());

        // VALIDATION at build(): missing symbol is rejected
        try {
            Order.builder().tradeId("TRD-1002").accountId("CUR3001").quantity(10)
                 .price(new BigDecimal("100")).build();
        } catch (IllegalStateException e) {
            log.warning("Rejected invalid order: " + e.getMessage());
        }
    }
}

// ─── Immutable Order built only through its Builder ───
class Order {
    private final String tradeId, accountId, symbol, orderType, notes;
    private final int quantity;
    private final BigDecimal price, fee;

    // private: only the Builder may construct an Order
    private Order(Builder b) {
        this.tradeId = b.tradeId; this.accountId = b.accountId; this.symbol = b.symbol;
        this.quantity = b.quantity; this.price = b.price; this.fee = b.fee;
        this.orderType = b.orderType; this.notes = b.notes;
    }
    static Builder builder() { return new Builder(); }

    BigDecimal totalCost() { return price.multiply(BigDecimal.valueOf(quantity)).add(fee); }
    public String toString() {
        return tradeId + " " + accountId + " " + symbol + " x" + quantity + " @" + price
             + " fee=" + fee + " type=" + orderType + (notes != null ? " note='" + notes + "'" : "");
    }

    // The Builder: holds mutable state, each setter returns 'this' for chaining
    static class Builder {
        private String tradeId, accountId, symbol, orderType = "MARKET", notes;
        private int quantity;
        private BigDecimal price, fee = BigDecimal.ZERO;

        Builder tradeId(String v)   { this.tradeId = v; return this; }
        Builder accountId(String v) { this.accountId = v; return this; }
        Builder symbol(String v)    { this.symbol = v; return this; }
        Builder quantity(int v)     { this.quantity = v; return this; }
        Builder price(BigDecimal v) { this.price = v; return this; }
        Builder fee(BigDecimal v)   { this.fee = v; return this; }
        Builder orderType(String v) { this.orderType = v; return this; }
        Builder notes(String v)     { this.notes = v; return this; }

        // build(): single validation choke point, returns immutable Order
        Order build() {
            if (tradeId == null)  throw new IllegalStateException("tradeId required");
            if (symbol == null)   throw new IllegalStateException("symbol required");
            if (quantity <= 0)    throw new IllegalStateException("quantity must be > 0");
            if (price == null || price.signum() <= 0) throw new IllegalStateException("price must be > 0");
            return new Order(this);
        }
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
